func (c *Client) Close() error {
    c.cancel()            // 1. 取消 context → 通知所有 goroutine 退出
    c.Watcher.Close()     // 2. 关闭 Watcher（停止所有 watch 流）
    c.Lease.Close()       // 3. 关闭 Lease（停止 keepalive 循环）
    if c.conn != nil {
        return c.conn.Close()  // 4. 最后关闭 gRPC 连接
    }
}
